package onl.ycode.stormify.biglist

/**
 * A type-safe field path node representing a scalar (leaf) field.
 * Generated by the annotation processor and used with [PagedList.addFacet][AbstractPagedList.addFacet].
 *
 * Example:
 * ```kotlin
 * list.addFacet(Employee_.name)               // scalar
 * list.addFacet(Employee_.department.name)     // FK chain
 * ```
 */
open class ScalarPath(
    private val path: String
) {
    /** Returns the dot-notation path string. */
    override fun toString() = path
}

/**
 * Base class for annotation-processor-generated reference path nodes (e.g.
 * `AuditEntry_.modifiedBy`). Each reference node carries the accumulated dot-notation
 * path it represents — with a trailing `.` when further chaining through this node is
 * still possible — and subclasses use [toString] to build the next path step when
 * chaining into nested reference or scalar fields.
 */
open class ReferencePath(
    private val path: String
) {
    /** Returns the accumulated dot-notation path. */
    override fun toString() = path
}
